import assert from "node:assert/strict";
import { test } from "node:test";
import { deepMerge } from "../src/merge.ts";

test("grader: deepMerge", () => {
  const a = { a: { b: 1, c: 2 }, x: [1, 2] };
  const b = { a: { b: 9 }, d: [1], x: [3] };
  const r = deepMerge(a, b);
  assert.deepEqual(r, { a: { b: 9, c: 2 }, d: [1], x: [3] });
  assert.deepEqual(a, { a: { b: 1, c: 2 }, x: [1, 2] });
  assert.deepEqual(b, { a: { b: 9 }, d: [1], x: [3] });
  deepMerge({}, JSON.parse('{"__proto__":{"polluted":true}}'));
  assert.equal(({} as Record<string, unknown>).polluted, undefined);
});

